// ── Keys Hubs ───────────────────────────────────────────────────────────────
// Each hub physically stores backup keys. An apartment can have key sets in
// MULTIPLE hubs (duplicates). Assignment: S.keyHubs[aptId] = [hubIds].
// Optional key tag in S.keyLabels[aptId]. On-site spare: S.keyLockbox[aptId].
// Proximity ranks hubs by distance to the apartment (Driver from its car base).
const KEY_HUBS = [
  { id:'votsala',   name:'Votsala',      addr:'Louka Ralli 59',              lat:37.9585, lng:23.6460 },
  { id:'verandas',  name:'Verandas',     addr:'Makri 19',                    lat:37.9686, lng:23.7285 },
  { id:'cholargos', name:'Cholargos',    addr:'17is Noemvriou 19',           lat:38.0030, lng:23.7950 },
  { id:'plynthrio', name:'Thessaloniki', addr:'Mitoudi 12',                  lat:40.6070, lng:22.9580 },
  { id:'driver',    name:'Driver',       addr:'Ilioupoli, Athens (car base)', lat:37.9315, lng:23.7678, mobile:true },
];
let _keyHubSearch = '';
function _khEsc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function _khJs(s){ return String(s==null?'':s).replace(/\\/g,'\\\\').replace(/'/g,"\\'"); }
function _keyHubName(id){ const h=KEY_HUBS.find(function(x){ return x.id===id; }); return h?h.name:''; }
function _keyHubsOf(aptId){
  const v = (S.keyHubs||{})[aptId];
  if (Array.isArray(v)) return v.slice();
  if (typeof v==='string' && v) return [v];
  return [];
}
function _keyLockbox(aptId){ return !!((S.keyLockbox||{})[aptId]); }
function _keyHubSave(){ if (typeof save==='function') save(); }
function opsToggleKeyHub(aptId, hubId){
  if (!S.keyHubs) S.keyHubs={};
  let arr=_keyHubsOf(aptId);
  const i=arr.indexOf(hubId);
  if (i>=0) arr.splice(i,1); else arr.push(hubId);
  if (arr.length) S.keyHubs[aptId]=arr; else delete S.keyHubs[aptId];
  _keyHubSave();
  renderKeyHubs();
}
function opsSetKeyLabel(aptId, label){
  if (!S.keyLabels) S.keyLabels={};
  const v=String(label||'').trim();
  if (v) S.keyLabels[aptId]=v; else delete S.keyLabels[aptId];
  _keyHubSave();
}
function opsToggleLockbox(aptId){
  if (!S.keyLockbox) S.keyLockbox={};
  if (_keyLockbox(aptId)) delete S.keyLockbox[aptId]; else S.keyLockbox[aptId]=true;
  _keyHubSave();
  renderKeyHubs();
}
function _keyHubSetSearch(v){
  _keyHubSearch=String(v||'');
  renderKeyHubs();
  const el=document.getElementById('kh-search');
  if (el) { el.focus(); try { el.setSelectionRange(el.value.length, el.value.length); } catch(e) {} }
}
function _keyHubDist(apt, hub){
  const la=parseFloat(apt&&apt.lat), ln=parseFloat(apt&&apt.lng);
  if (!isFinite(la)||!isFinite(ln)||!isFinite(hub.lat)||!isFinite(hub.lng)) return null;
  const R=6371, toRad=function(d){ return d*Math.PI/180; };
  const dLat=toRad(hub.lat-la), dLng=toRad(hub.lng-ln);
  const a=Math.sin(dLat/2)*Math.sin(dLat/2)+Math.cos(toRad(la))*Math.cos(toRad(hub.lat))*Math.sin(dLng/2)*Math.sin(dLng/2);
  return 2*R*Math.asin(Math.sqrt(a));
}
function _keyHubDists(apt){
  return KEY_HUBS.map(function(h){ return { h:h, d:_keyHubDist(apt,h) }; })
    .filter(function(x){ return x.d!=null; })
    .sort(function(x,y){ return x.d-y.d; });
}
function _keyHubMatch(a, q){
  if (!q) return true;
  const have=_keyHubsOf(a.id);
  const bits=[a.name, a.aliases, a.city, (S.keyLabels||{})[a.id]];
  have.forEach(function(id){ bits.push(_keyHubName(id)); bits.push(id); });
  if (_keyLockbox(a.id)) bits.push('lockbox');
  if (!have.length && !_keyLockbox(a.id)) bits.push('no key');
  return bits.join(' ').toLowerCase().indexOf(q)>=0;
}
function renderKeyHubs(){
  const panel=document.getElementById('tab-keys');
  if (!panel) return;
  const apts=Array.isArray(S.apts)?S.apts.slice():[];
  const labels=S.keyLabels||{};
  const q=_keyHubSearch.trim().toLowerCase();
  apts.sort(function(a,b){
    try { return String(a.name||'').localeCompare(String(b.name||''),'el',{numeric:true}); }
    catch(e){ return String(a.name||'').localeCompare(String(b.name||'')); }
  });
  const shown=apts.filter(function(a){ return _keyHubMatch(a,q); });
  const hubCount={}; KEY_HUBS.forEach(function(h){ hubCount[h.id]=0; });
  apts.forEach(function(a){ _keyHubsOf(a.id).forEach(function(hid){ if (hubCount[hid]!=null) hubCount[hid]++; }); });
  const noKeyCount=apts.filter(function(a){ return _keyHubsOf(a.id).length===0 && !_keyLockbox(a.id); }).length;
  const lockboxCount=apts.filter(function(a){ return _keyLockbox(a.id); }).length;
  const hubChip=function(aptId, hub, active){
    const cls=active?'kh-chip on kh-chip-'+hub.id:'kh-chip';
    const title=active?'Key stored here — click to remove':'Add a key set here';
    return '<button type="button" class="'+cls+'" onclick="opsToggleKeyHub(\''+_khJs(aptId)+'\',\''+hub.id+'\')" title="'+_khEsc(title)+'">'+_khEsc(hub.name)+'</button>';
  };
  const aptRow=function(a){
    const have=_keyHubsOf(a.id);
    const lbl=_khEsc(labels[a.id]||'');
    const hasLockbox=_keyLockbox(a.id);
    const dists=_keyHubDists(a);
    const nearest=dists.length?dists[0]:null;
    const nearestWithKey=dists.find(function(x){ return have.indexOf(x.h.id)>=0; })||null;
    const icon=function(h){ return h.mobile?'🚗':'📍'; };
    let proxCell;
    if (hasLockbox){
      proxCell='<span class="kh-near kh-near-lockbox">🔒 On-site lockbox</span>';
      if (nearestWithKey) proxCell+='<div class="kh-near-sub">also: '+icon(nearestWithKey.h)+' '+_khEsc(nearestWithKey.h.name)+' ('+nearestWithKey.d.toFixed(1)+'km)</div>';
    } else if (!dists.length){
      proxCell='<span style="color:var(--tx3)">—</span>';
    } else {
      const nk=nearestWithKey
        ? '<span class="kh-near kh-chip-'+nearestWithKey.h.id+'">'+icon(nearestWithKey.h)+' '+_khEsc(nearestWithKey.h.name)+' · '+nearestWithKey.d.toFixed(1)+'km</span>'
        : '<span style="color:var(--tx-warn);font-size:11.5px">no key nearby</span>';
      const closestNote=(nearest && (!nearestWithKey || nearestWithKey.h.id!==nearest.h.id))
        ? '<div class="kh-near-sub">closest hub: '+icon(nearest.h)+' '+_khEsc(nearest.h.name)+' ('+nearest.d.toFixed(1)+'km)</div>' : '';
      proxCell=nk+closestNote;
    }
    const lockboxTag=hasLockbox?' <span class="kh-tag-lockbox" title="A spare key is kept in the property on-site lockbox">🔒 LOCKBOX</span>':'';
    const lockChip='<button type="button" class="kh-chip kh-chip-lockbox'+(hasLockbox?' on':'')+'" onclick="opsToggleLockbox(\''+_khJs(a.id)+'\')" title="'+(hasLockbox?'Spare key in on-site lockbox — click to remove':'Mark that a spare key is in the property lockbox')+'">🔒 Lockbox</button>';
    return '<tr>'
      +'<td style="font-weight:600;color:var(--tx)">'+_khEsc(a.name||'')
        +(have.length===0 && !hasLockbox?' <span class="kh-nokey">no key</span>':'')+lockboxTag+'</td>'
      +'<td><input type="text" value="'+lbl+'" placeholder="key tag…" onchange="opsSetKeyLabel(\''+_khJs(a.id)+'\',this.value)" class="kh-inp"></td>'
      +'<td><div class="kh-chips">'+KEY_HUBS.map(function(h){ return hubChip(a.id,h,have.indexOf(h.id)>=0); }).join('')+lockChip+'</div></td>'
      +'<td style="min-width:150px">'+proxCell+'</td>'
      +'</tr>';
  };
  const rowsHtml=shown.length
    ? shown.map(aptRow).join('')
    : '<tr><td colspan="4" style="color:var(--tx3);font-style:italic;padding:14px">'+(apts.length?'No apartments match your search.':'No apartments loaded yet — sync from Hosthub.')+'</td></tr>';
  panel.innerHTML='<div class="kh-wrap">'
    +'<div class="kh-head"><div><h2 class="kh-title">Keys Hubs</h2>'
    +'<div class="kh-sub">Backup keys for '+apts.length+' apartments · click a hub chip to store or remove a key set (an apartment can be in several hubs)</div></div>'
    +'<input id="kh-search" type="text" placeholder="Search apartment, tag, or hub…" value="'+_khEsc(_keyHubSearch)+'" oninput="_keyHubSetSearch(this.value)" class="kh-search">'
    +'</div>'
    +'<div class="kh-stats">'
    +KEY_HUBS.map(function(h){ return '<div class="kh-stat"><div class="kh-stat-val kh-chip-'+h.id+'" style="background:none;padding:0">'+hubCount[h.id]+'</div><div class="kh-stat-lbl">'+_khEsc(h.name)+(h.mobile?' 🚗':'')+'</div><div class="kh-stat-addr">'+_khEsc(h.addr)+'</div></div>'; }).join('')
    +'<div class="kh-stat"><div class="kh-stat-val" style="color:#8b5cf6">'+lockboxCount+'</div><div class="kh-stat-lbl">🔒 Lockbox</div></div>'
    +'<div class="kh-stat"><div class="kh-stat-val" style="color:var(--tx-warn)">'+noKeyCount+'</div><div class="kh-stat-lbl">No key set</div></div>'
    +'</div>'
    +'<div class="kh-card"><table class="kh-table"><thead><tr>'
    +'<th>Apartment</th><th style="width:150px">Key tag</th><th>Key locations</th><th style="width:170px">Nearest key</th>'
    +'</tr></thead><tbody>'+rowsHtml+'</tbody></table></div></div>';
}

function opsManageCleaners() {
